export abstract class SimpleChatModel {
  public abstract doGenerate(data: BaseChatModelInput, options?: ReqOptions): Promise<DoGenerateOutput>

  public abstract doStream(data: BaseChatModelInput, options?: ReqOptions): Promise<DoStreamOutput>
}

type RawResponse = { rawResponse?: any }

export type DoGenerateOutput = BaseDoGenerateOutput & RawResponse

export type DoStreamOutput = AsyncIterableReadableStream<BaseDoStreamOutputChunk & RawResponse>

export type ChatModelConstructor = typeof SimpleChatModel

export type AsyncIterableReadableStream<T> = ReadableStream<T> & {
  [Symbol.asyncIterator]: () => { next(): Promise<IteratorResult<T>> }
}

export interface IModelReqInput {
  url: string
  headers?: Record<string, string>
  data?: Object
  stream?: boolean
  timeout?: number
}

export type ModelReq = <T extends IModelReqInput>(
  props: T,
) => T['stream'] extends true ? Promise<ReadableStream<Uint8Array>> : Promise<Object>

export interface IBotReqInput {
  url: string
  method: string
  headers?: Record<string, string>
  data?: Object
  stream?: boolean
  timeout?: number
}

export interface ReqOptions {
  timeout?: number
}

export type BotReq = <T extends IBotReqInput>(
  props: T,
) => T['stream'] extends true ? Promise<ReadableStream<Uint8Array>> : Promise<Object>

export type UserMessage = {
  role: 'user'
  content: string
}

export type SystemMessage = {
  role: 'system'
  content: string
}

export type AssistantMessage = PlainAssistantMessage | ToolCallAssistantMessage

export type PlainAssistantMessage = {
  role: 'assistant'
  content: string
}

export type ToolCallAssistantMessage = {
  role: 'assistant'
  tool_calls: Array<ToolCall>
  content?: string
}

export type ToolMessage = {
  role: 'tool'
  tool_call_id: string
  content: string
}

export type ChatModelMessage = UserMessage | SystemMessage | AssistantMessage | ToolMessage

export type FunctionTool = {
  name: string
  description: string
  fn: CallableFunction
  parameters: object
}

// #region 大模型标准输入类型
export interface BaseChatModelInput {
  model: string
  messages: Array<ChatModelMessage>
  temperature?: number
  top_p?: number
  tools?: Array<ModelTool>
  tool_choice?: 'none' | 'auto' | 'custom'
}

/**
 * 给 LLM 发请求时要传的工具
 */
export type ModelTool = {
  type: string
  function: ModelToolFunction
}

/**
 * 给 LLM 发请求时要传的工具函数
 */
export type ModelToolFunction = {
  name: string
  description: string
  /**
   * 描述函数参数的 JSON Schema
   */
  parameters: object
}
// #endregion

// #region 大模型标准响应类型
export type ToolCall = {
  id: string
  type: string
  function: { name: string; arguments: string }
}

type FinishReason = 'tool_calls' | (string & {})

export type Usage = {
  completion_tokens: number
  prompt_tokens: number
  total_tokens: number
}

export interface BaseDoGenerateOutput {
  choices?: Array<{
    finish_reason?: FinishReason
    message?: ChatModelMessage
  }>
  usage?: Usage
}

export interface BaseDoStreamOutputChunk {
  choices?: Array<{
    finish_reason?: FinishReason
    delta?: ChatModelMessage
  }>
  usage?: Usage
}
// #endregion

// #region Image Model Types
/**
 * 图片生成输入参数
 */
export interface ImageGenerateInput {
  model: string // 模型名称，例如 'hunyuan-image'、'dall-e-3'
  prompt: string // 用于描述要生成的图片内容
  size?: string // 尺寸
  n?: number // 张数
  [key: string]: unknown // 允许额外的厂商特定参数
}

/**
 * 图片编辑输入参数
 */
export interface ImageEditInput {
  model: string
  prompt: string
  size?: string // 尺寸
  n?: number // 张数
  [key: string]: unknown // 允许额外的厂商特定参数
}

export interface HunyuanGenerateImageInput {
  model: 'hunyuan-image'
  /** 用来生成图像的文本描述 */
  prompt: string
  /**
   * 模型版本，支持 v1.8.1 和 v1.9，默认版本 v1.8.1
   * - v1.8.1: 采用二阶段模型支持文生图任务，针对图像细节、稳定性等要求高的任务较为合适
   * - v1.9: 采用模型矩阵能力支持文生图任务，后端由人像、游戏、通用模型，以及各类功能插件组成，灵活适配多种文生图任务
   */
  version?: 'v1.8.1' | 'v1.9' | (string & {})
  /**
   * 图片尺寸，默认 "1024x1024"
   * v1.9 仅支持以下几个尺寸：
   * - 1024x1024
   * - 1024x768, 1152x864
   * - 768x1024, 864x1152
   * - 1280x768 (16:9)
   * - 768x1280 (9:16)
   * - 1280x720 (16:9)
   * - 720x1280 (9:16)
   *
   * 支持用户自定义尺寸，但输入尺寸只支持 768-1280 之间且为 64 的倍数的数字
   */
  size?: string
  /**
   * 仅 v1.9 支持，负向词
   * 如果不传则使用各个模型内部的默认负向词
   */
  negative_prompt?: string
  /**
   * 仅 v1.9 支持，可指定风格：
   * - 古风二次元风格
   * - 都市二次元风格
   * - 悬疑风格
   * - 校园风格
   * - 都市异能风格
   */
  style?: '古风二次元风格' | '都市二次元风格' | '悬疑风格' | '校园风格' | '都市异能风格' | (string & {})
  /**
   * 为 true 时对 prompt 进行改写，实际生成的图片会使用改写后的 prompt 进行生成
   * 多数场景可提升生成的图片效果，默认为 true
   */
  revise?: boolean
  /**
   * 生成图片个数，默认为 1
   * 目前只支持生成一张，固定为 1，传其他的值会报错
   */
  n?: number
  /**
   * 业务自定义水印内容
   * 限制 16 个字符长度（不区分中英文），生成在图片右下角
   */
  footnote?: string
  /**
   * 生成种子，仅当生成图片数为 1 时生效
   * 范围 [1, 4294967295]，不传时默认随机
   */
  seed?: number
}

export interface HunyuanARGenerateImageInput {
  /** 模型名称：hunyuan-image-v3.0-v1.0.4（推荐）、hunyuan-image-v3.0-v1.0.1 或 HY-Image-v3.0-I2I-ToB-v1.0.1 */
  model: 'hunyuan-image-v3.0-v1.0.4' | 'hunyuan-image-v3.0-v1.0.1' | 'HY-Image-v3.0-I2I-ToB-v1.0.1' | 'HY-Image-3.0-Plus-4090-Tob-v1.0'
  /** 生成图片使用的文本，不超过 8192 字符 */
  prompt: string
  /**
   * 图片尺寸，格式 "${宽}x${高}"，默认 "1024x1024"
   * hunyuan-image-v3.0-v1.0.4：宽高 [512, 2048]，面积不超过 1024x1024
   * hunyuan-image-v3.0-v1.0.1：支持固定尺寸列表
   */
  size?: string
  /** 生成种子，仅当生成图片数为 1 时生效，范围 [1, 4294967295] */
  seed?: number
  /** 业务自定义水印内容，限制 16 字符，生成在图片右下角 */
  footnote?: string
  /** 是否对 prompt 改写，默认开启。改写会增加约 30s 耗时 */
  revise?: { value: boolean }
  /** 改写是否开启 thinking 模式，默认开启。开启后效果提升但耗时增加（最大 60s） */
  enable_thinking?: { value: boolean }
  /**
   * 改写图片地址
   */
  image_urls?: string[]
  images?: string[]
}

export interface HunyuanARGenerateImageOutput {
  /** 此次请求的 id */
  id: string
  /** unix 时间戳 */
  created: number
  /** 返回的图片生成内容 */
  data: Array<{
    /** 生成的图片 url，有效期 24 小时 */
    url: string
    /** 改写后的 prompt */
    revised_prompt?: string
  }>
}

// #region Image Chat Types (OpenAI Chat Completions 风格 messages)
// 用于 Hy-Image-3.5-preview 等以 Chat/Messages 协议提交的生图模型。
// 注意：这是 OpenAI Chat Completions 风格的协议，并非 OpenAI 完整标准，
// 其中 reasoning、is_generate 为服务端扩展字段。

/** Chat messages 中的文本内容块 */
export interface ChatContentPartText {
  type: 'text'
  /** 具体文本内容 */
  text: string
}

/** Chat messages 中的图片内容块 */
export interface ChatContentPartImageUrl {
  type: 'image_url'
  /** 支持 http(s) 公网 URL 或 data:image/...;base64,... */
  image_url: {
    url: string
  }
  /** 仅 role=tool 回灌上一轮生图结果时为 true */
  is_generate?: boolean
}

export type ChatContentPart = ChatContentPartText | ChatContentPartImageUrl

/** OpenAI Chat Completions 风格的会话消息 */
export interface ChatMessage {
  /** 角色。tool 仅在把上一轮生图结果回灌作为下一轮上下文时出现 */
  role: 'user' | 'assistant' | 'tool'
  /** 该轮的具体内容，assistant 仅触发工具调用、不发文本时可省略 */
  content?: ChatContentPart[]
  /** 仅 role=assistant 多轮回灌时使用，透传上一轮响应中的思维链原文 */
  reasoning?: string
  /** 仅 role=assistant 多轮回灌时使用，元素结构见 ToolCall */
  tool_calls?: ToolCall[]
  /** 仅 role=tool 多轮回灌时使用，须与上一条 assistant.tool_calls[i].id 一致 */
  tool_call_id?: string
}

export interface CloudbaseGenerateImageInput {
  /** 模型名称：Hy-Image-3.5-preview，协议取值为 hy-image-v3.5-preview */
  model: 'hy-image-v3.5-preview'
  /** 多轮会话内容，时间从旧到新排列。最后一个 role=user 的消息作为本轮生图指令 */
  messages: ChatMessage[]
  /**
   * 生成尺寸，格式 "${宽}x${高}"
   * 宽高均为 [256, 8192]，面积不超过 16777216（最高 4096x4096）
   * 不传或传空串时由模型基于 prompt 语义与 generate_max_pixels 自主决定
   */
  size?: string
  /** 生成种子，int64 范围 [0, 2^63-1]；为 0 或不传时服务端随机分配 */
  seed?: number
  /**
   * 生成图片的目标面积（像素数），仅在未传 size 时生效
   * 支持 1048576（1K）、2359296（1.5K，默认）、4194304（2K）
   */
  generate_max_pixels?: number
  /** 输入参考图面积上限（像素数），默认 1048576 */
  resize_max_pixels?: number
  /** 会话 ID，用于推理服务一致性哈希调度 */
  session?: string
  /** 业务自定义水印内容，最长 16 字符，生成在图片右下角 */
  footnote?: string
  /** 外部搜索增强开关，默认关闭 */
  use_search_tool?: { value: boolean }
}

export interface CloudbaseGenerateImageOutput {
  /** 此次请求的 traceID */
  id: string
  /** 固定 image.chat.completion.chunk */
  object: string
  /** Unix 秒级时间戳 */
  created: number
  /** 原厂实际服务返回的内部版本标识，不建议用于业务分支判断 */
  model: string
  /** 本帧所属 LLM 轮次，从 0 起算 */
  round: number
  choices: Array<{
    index: number
    /** 主图载体，成功时优先读取 delta.image.url 作为最终交付 URL */
    delta: {
      type?: string
      image?: {
        /** 本次生图的最终交付 URL，有效期 12 小时 */
        url: string
        width: number
        height: number
        source: string
        tool_call_id: string
      }
    }
    /** 成功终态下往往为 null；内容安全拦截/业务错误时为 error 等非空值 */
    finish_reason?: string | null
  }>
  usage?: { total_tokens: number }
  tokenhub_usage?: { total_tokens: number }
  request_id?: string
  /** 服务端拼好的「下一轮回灌消息序列」，多轮编辑时原样追加到下一轮 messages */
  assembled_history?: ChatMessage[]
  /** 仅失败终态帧才带 */
  error?: {
    type: string
    code: string
    message: string
    request_id?: string
  }
}

// #endregion

export type HunyuanEditImageInput = {
  /** 模型名称，本期为 hunyuan-image，即为商品图编辑场景 */
  model: 'hunyuan-image' | (string & {})
  /** 编辑的文本描述 */
  prompt: string
  /** 模型版本 */
  version?: string
  /**
   * 图片尺寸，默认 "800x800"
   * 支持用户自定义尺寸，但输入尺寸只支持 512-1280 之间
   * 目前只支持 1:1、16:9、9:16 三个尺寸
   */
  size?: string
  /**
   * 生成图片个数，默认为 1
   * 目前只支持生成一张，固定为 1，传其他的值会报错
   */
  n?: number
  /**
   * beta 参数，随机种子
   * 范围 [1, 4294967295]，不传时默认随机
   */
  seed?: number
  /**
   * 业务自定义角标内容
   * 限制 16 个字符长度（不区分中英文）
   */
  footnote?: string
  /**
   * 图 base64 编码，大小不超过 6M
   * 支持 jpg/jpeg 格式，和 image_url 二选一
   * 长短边比例要求 2:1 内
   */
  image?: string
  /**
   * 图片 url
   * 长短边比例要求 2:1 内，和 image 二选一
   */
  image_url?: string
} & (
  | {
    mask: string
    mask_url?: never
  }
  | {
    mask?: never
    mask_url: string
  }
)

/**
 * 混元图片生成输出
 */
export interface HunyuanGenerateImageOutput {
  /** 此次请求的 id */
  id: string
  /** unix 时间戳 */
  created: number
  /** 返回的图片生成内容 */
  data: Array<{
    /** 生成的图片 url，有效期为 24 小时 */
    url: string
    /** 原 prompt 改写后的文本。若 revise 为 false，则为原 prompt */
    revised_prompt?: string
  }>
}

/**
 * 混元图片编辑输出
 */
export interface HunyuanEditImageOutput {
  /** 此次请求的 id */
  id: string
  /** unix 时间戳 */
  created: number
  /** 返回的图片生成内容 */
  data: Array<{
    /** 生成的图片 url，有效期为 24 小时 */
    url: string
  }>
}

// #endregion
